#include <cstdio>
#include <algorithm>
using namespace std;

int mod;
inline int add_mod(int x) {
    return x >= mod ? x - mod : x;
}
inline int sub_mod(int x) {
    return x < 0 ? x + mod : x;
}
int bin_pow(int base, int exp) {
    int res=1;
    while (exp > 0) {
        if (exp & 1) res = (long long)res * base % mod;
        base = (long long)base * base % mod;
        exp >>= 1;
    }
    return res;
}
struct Data {
    int f, g;
    Data(int f=0, int g=0):f(f), g(g) {}
};
Data operator+(const Data &a, const Data &b) {
    return Data(add_mod(a.f + b.f), add_mod(a.g + b.g));
}
Data operator*(const Data &a, const Data &b) {
    return Data((long long)a.f * b.f % mod, add_mod((long long)a.f * b.g % mod + (long long)a.g * b.f % mod));
}
int n, m, maxN=100000;
int fact[100005], inv_fact[100005], inv_num[100005];
Data dp[1005], table[1005][1005];

int sum_series(int x) {
    return (long long)x * (x+1) / 2 % mod;
}

int main() {
    scanf("%d%d%d", &n, &m, &mod);
    fact[0]=inv_fact[0]=1;
    for (int i=1; i<=maxN; i++) {
        fact[i] = (long long)i * fact[i-1] % mod;
        inv_fact[i] = bin_pow(fact[i], mod-2);
        inv_num[i] = bin_pow(i, mod-2);
    }
    dp[0] = Data(1,0);
    for (int i=1; i<=n; i++) {
        for (int j=1; j<=i; j++) {
            Data temp = dp[j-1] * dp[i-j];
            temp.g = add_mod((long long)temp.g * (i+1) % mod + (long long)temp.f * add_mod(sum_series(j-1) + sum_series(i-j)) % mod);
            temp.g = (long long)temp.g * inv_num[i] % mod;
            temp.f = (long long)temp.f * (i+1) % mod * inv_num[i] % mod;
            dp[i] = dp[i] + temp;
        }
    }
    table[0][0] = Data(1,0);
    for (int i=1; i<=n; i++) {
        for (int j=0; j<=min(i,m); j++) {
            if (i==j) table[i][j]=dp[i];
            for (int k=0; k<j && k<i; k++) {
                table[i][j]=table[i][j]+dp[k]*table[i-k-1][j-k];
            }
        }
    }
    int answer= (long long)table[n][m].g*fact[m]%mod;
    printf("%d\n", answer);
    return 0;
}
